var t=`0758-sukuma-wiki`;var n=`world-0758`;var a=`KE`;var s=`eastern-africa`;var o=4;var r=31;var l={en:`Sukuma Wiki`,ua:`Сукума вікі`};var g={en:`Sukuma Wiki is a Kenya classic prepared with yellow onion, tomato, garlic, collard greens. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Сукума вікі, страва кухні країни Кенія зі складниками: жовта цибуля, помідор, часник, листова капуста колард. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,180,`g`],[`tomato`,230,`g`],[`sunflower-oil`,40,`ml`],[`garlic`,3,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 16 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 16 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:16,i:[[`collard-greens`,560,`g`],[`water`,140,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`lemon-juice`,25,`ml`],[`table-salt`,null,`to_taste`]]}];var d={slug:t,id:n,country:`KE`,region:s,servings:4,minutes:31,title:l,text:g,steps:u};export{a as country,d as default,n as id,r as minutes,s as region,o as servings,t as slug,u as steps,g as text,l as title};